using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;using System.Linq;using System.Collections.Generic;
sealed partial class WorkspaceWindow {
 void AddHomeQuickAccess(FlowLayoutPanel grid){
  var pulse=new Button{Text="Jago Pulse\n\nMusic-driven films and visuals",Name="pulseHome",Size=new Size(265,120),Margin=new Padding(0,0,16,16),TextAlign=ContentAlignment.MiddleLeft,Padding=new Padding(16),FlatStyle=FlatStyle.Flat};
  using(var stream=typeof(WorkspaceWindow).Assembly.GetManifestResourceStream("Jago.Icon.pulse.png")){if(stream!=null)using(var im=Image.FromStream(stream))pulse.Image=new Bitmap(im,new Size(40,40));}pulse.ImageAlign=ContentAlignment.MiddleLeft;pulse.TextImageRelation=TextImageRelation.ImageBeforeText;pulse.Click+=(s,e)=>LaunchPulse();grid.Controls.Add(pulse);
  var group=new Panel{Name="homeQuickTools",Size=new Size(265,120),Margin=new Padding(0,0,16,16)};group.Controls.Add(new Label{Text="Quick access",AutoSize=true,Location=new Point(0,0)});
  foreach(string tool in new[]{"Capture","Board"}){string name=tool;var button=new Button{Name="quick"+tool,Text=tool,AccessibleName="Jago "+tool+" quick access",AccessibleDescription=tool=="Capture"?"Open Capture. Right-click for region, window and video options.":"Open your reference board. Right-click for a new board or full Library.",Size=new Size(94,88),Location=new Point(tool=="Capture"?0:106,28),Padding=new Padding(7),FlatStyle=FlatStyle.Flat,TextImageRelation=TextImageRelation.ImageAboveText,ImageAlign=ContentAlignment.TopCenter,TextAlign=ContentAlignment.BottomCenter,Image=QuickIcon(tool,ForeColor)};button.Click+=(s,e)=>LaunchQuickTool(name,"");var menu=new ContextMenuStrip();var choices=tool=="Capture"?new[]{Tuple.Create("Capture a region","--region"),Tuple.Create("Capture a window","--window"),Tuple.Create("Record a video snippet…","--video"),Tuple.Create("Choose capture action…","--menu")}:new[]{Tuple.Create("Open last board",""),Tuple.Create("New board…","--new"),Tuple.Create("Boards in this collection","--recent"),Tuple.Create("Open full Library","--library")};foreach(var pair in choices){string arg=pair.Item2;menu.Items.Add(pair.Item1,null,(s,e)=>LaunchQuickTool(name,arg));}menu.Opening+=(s,e)=>{menu.BackColor=BackColor;menu.ForeColor=ForeColor;foreach(ToolStripItem item in menu.Items){item.BackColor=BackColor;item.ForeColor=ForeColor;}};button.ContextMenuStrip=menu;var tip=new ToolTip();tip.SetToolTip(button,button.AccessibleDescription);FormClosed+=(s,e)=>{menu.Dispose();tip.Dispose();button.Image.Dispose();};group.Controls.Add(button);}grid.Controls.Add(group);
 }
 Bitmap QuickIcon(string tool,Color colour){var bitmap=new Bitmap(32,32);using(var g=Graphics.FromImage(bitmap)){g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;g.Clear(Color.Transparent);using(var p=new Pen(colour,2.5f)){if(tool=="Capture"){g.DrawRectangle(p,3,8,26,20);g.DrawEllipse(p,11,13,10,10);g.DrawLine(p,7,4,16,4);}else{g.DrawRectangle(p,2,3,28,26);g.DrawRectangle(p,6,7,9,10);g.DrawRectangle(p,19,7,7,6);g.DrawRectangle(p,6,21,9,4);g.DrawRectangle(p,19,17,7,8);}}}return bitmap;}
 string QuickToolPath(string tool){string parent=Exe(tool=="Capture"?"companion":"library"),name=tool=="Capture"?"Jago-Capture.exe":"Jago-Board.exe",path=Path.Combine(Path.GetDirectoryName(parent),name);if(!File.Exists(path))throw new FileNotFoundException(name+" is missing beside your selected "+(tool=="Capture"?"Companion":"Library")+" release. Choose a current release in Manage studios.");return path;}
 ProcessStartInfo QuickStartInfo(string tool,string arguments){var path=QuickToolPath(tool);var info=new ProcessStartInfo(path,arguments){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(path)};foreach(string key in new[]{"JAGO_WORKSPACE_ROOT","JAGO_WORKSPACE_TAB_ROOT","JAGO_WORKSPACE_TAB_ID"})info.EnvironmentVariables.Remove(key);return info;}
 void LaunchQuickTool(string tool,string arguments){try{Process.Start(QuickStartInfo(tool,arguments));SetStatus("Opening Jago "+tool+"…");}catch(Exception e){SetStatus(e.Message);MessageBox.Show(this,e.Message,"Jago "+tool,MessageBoxButtons.OK,MessageBoxIcon.Information);}}
}
